'use client';

import { useEffect } from 'react';

/**
 * Registers `/sw.js` so the app keeps working offline after the first visit.
 * Production only: the worker is generated by `npm run build` and would serve
 * stale files during development. Offline support is an enhancement, so a
 * failed registration is ignored.
 */
export function ServiceWorkerRegistrar(): null {
  useEffect(() => {
    if (process.env.NODE_ENV !== 'production' || !('serviceWorker' in navigator)) return;

    const register = () => {
      navigator.serviceWorker.register('/sw.js').catch(() => undefined);
    };

    if (document.readyState === 'complete') {
      register();
      return;
    }
    window.addEventListener('load', register, { once: true });
    return () => window.removeEventListener('load', register);
  }, []);

  return null;
}
